// ─── File: src/main/java/com/bank/hierarchy/model/Auditable.java ───
package com.bank.hierarchy.model;

import jakarta.persistence.*;
import java.time.LocalDateTime;

@MappedSuperclass   // NOT an entity, no table — only shares columns + callback
public abstract class Auditable {
    @Column(name = "created_at", nullable = false)
    private LocalDateTime createdAt;
    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @PrePersist   // inherited by every subclass → stamps audit fields on insert
    void stamp() {
        if (createdAt == null) createdAt = LocalDateTime.now();
        if (createdBy == null) createdBy = "system";
    }
    public LocalDateTime getCreatedAt() { return createdAt; }
}
```

