// ─── File: src/main/java/com/bank/hierarchy/model/Account.java ───
package com.bank.hierarchy.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity                                          // REAL entity → polymorphic queries
@Table(name = "accounts")
@Inheritance(strategy = InheritanceType.SINGLE_TABLE)
@DiscriminatorColumn(name = "account_type", discriminatorType = DiscriminatorType.STRING)
public abstract class Account extends Auditable { // inherits audit columns too
    @Id protected String id;
    protected BigDecimal balance;

    protected Account() { }
    public String getId() { return id; }
    public BigDecimal getBalance() { return balance; }
    public abstract String kind();   // polymorphic behaviour
}
```

