// ─── File: src/main/java/com/bank/hierarchy/service/AccountQueryService.java ───
package com.bank.hierarchy.service;

import com.bank.hierarchy.model.Account;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Slf4j
public class AccountQueryService {

    @PersistenceContext
    private EntityManager em;

    // POLYMORPHIC query — only possible because Account is a real @Entity hierarchy
    @Transactional(readOnly = true)
    public void listAllAccounts() {
        List<Account> all = em.createQuery("select a from Account a", Account.class)
                              .getResultList();
        for (Account a : all) {
            log.info("{} balance={} kind={} created={}",
                    a.getId(), a.getBalance(), a.kind(), a.getCreatedAt());
        }
    }
}
```
